import { mockDelete, mockGet, mockPost, mockPut, mockPutBinary, mockPathExists } from "@/features/mock-data";

const csrfStorageKey = "autostream.csrf_token";

export class APIError extends Error {
  status: number;
  code?: string;
  detailCode?: string;
  responseContentType?: string;

  constructor(message: string, status: number, code?: string, responseContentType?: string, detailCode?: string) {
    super(message);
    this.name = "APIError";
    this.status = status;
    this.code = code;
    this.detailCode = detailCode;
    this.responseContentType = responseContentType;
  }
}

export function getCSRFToken() {
  if (typeof window === "undefined") return "";
  return window.sessionStorage.getItem(csrfStorageKey) || "";
}

export function setCSRFToken(value?: string) {
  if (typeof window === "undefined" || !value) return;
  window.sessionStorage.setItem(csrfStorageKey, value);
}

export function clearCSRFToken() {
  if (typeof window === "undefined") return;
  window.sessionStorage.removeItem(csrfStorageKey);
}

export async function apiGet<T>(path: string, signal?: AbortSignal): Promise<T> {
  if (forceMock()) return mockGet(path) as T;
  try {
    const response = await fetch(path, {
      method: "GET",
      // React Query owns reusable API data. A fresh authority read must reach
      // the server even while Chrome holds an older same-URL GET in flight.
      cache: "no-store",
      signal,
      credentials: "same-origin",
      headers: { Accept: "application/json" },
    });
    return await readJSONResponse<T>(response, path);
  } catch (error) {
    if (signal?.aborted) throw error;
    if (canUseMockFallback(path)) return mockGet(path) as T;
    throw error;
  }
}

export async function apiPost<T>(path: string, body?: unknown, signal?: AbortSignal, correlation?: Readonly<{ requestID: string }>): Promise<T> {
  if (correlation && !/^[A-Za-z0-9_.:-]{1,80}$/.test(correlation.requestID)) throw new APIError("Invalid request correlation.", 0, "invalid_request_correlation");
  if (forceMock()) return mockPost(path, body) as T;
  try {
    const response = await fetch(path, {
      method: "POST",
      signal,
      credentials: "same-origin",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
        "X-CSRF-Token": getCSRFToken(),
        ...(correlation ? { "X-AutoStream-Request-ID": correlation.requestID } : {}),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    return await readJSONResponse<T>(response, path);
  } catch (error) {
    if (signal?.aborted) throw error;
    if (canUseMockFallback(path)) return mockPost(path, body) as T;
    throw error;
  }
}

export async function apiPostForm<T>(path: string, body: FormData, signal?: AbortSignal): Promise<T> {
  const response = await fetch(path, {
    method: "POST",
    signal,
    credentials: "same-origin",
    headers: {
      Accept: "application/json",
      "X-CSRF-Token": getCSRFToken(),
    },
    body,
  });
  return readJSONResponse<T>(response, path);
}

export async function apiPut<T>(path: string, body?: unknown, signal?: AbortSignal): Promise<T> {
  if (forceMock()) return mockPut(path, body) as T;
  try {
    const response = await fetch(path, {
      method: "PUT",
      signal,
      credentials: "same-origin",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
        "X-CSRF-Token": getCSRFToken(),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    return await readJSONResponse<T>(response, path);
  } catch (error) {
    if (signal?.aborted) throw error;
    if (canUseMockFallback(path)) return mockPut(path, body) as T;
    throw error;
  }
}

export async function apiPutBinary<T>(path: string, body: Blob, signal?: AbortSignal): Promise<T> {
  if (forceMock()) return mockPutBinary(path, body) as Promise<T>;
  try {
    const response = await fetch(path, {
      method: "PUT",
      signal,
      credentials: "same-origin",
      headers: {
        Accept: "application/json",
        "Content-Type": body.type || "application/octet-stream",
        "X-CSRF-Token": getCSRFToken(),
      },
      body,
    });
    const contentType = response.headers.get("content-type") || "";
    if (!contentType.includes("application/json") && canUseMockFallback(path)) {
      return mockPutBinary(path, body) as Promise<T>;
    }
    return await readJSONResponse<T>(response, path);
  } catch (error) {
    if (signal?.aborted) throw error;
    if (canUseMockFallback(path)) return mockPutBinary(path, body) as Promise<T>;
    throw error;
  }
}

export async function apiDelete<T>(path: string, signal?: AbortSignal): Promise<T> {
  if (forceMock()) return mockDelete(path) as T;
  try {
    const response = await fetch(path, {
      method: "DELETE",
      signal,
      credentials: "same-origin",
      headers: {
        Accept: "application/json",
        "X-CSRF-Token": getCSRFToken(),
      },
    });
    return await readJSONResponse<T>(response, path);
  } catch (error) {
    if (signal?.aborted) throw error;
    if (canUseMockFallback(path)) return mockDelete(path) as T;
    throw error;
  }
}

export async function apiDeleteJSON<T>(path: string, body: unknown, signal?: AbortSignal): Promise<T> {
  if (forceMock()) return mockDelete(path) as T;
  const response = await fetch(path, {
    method: "DELETE",
    signal,
    credentials: "same-origin",
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      "X-CSRF-Token": getCSRFToken(),
    },
    body: JSON.stringify(body),
  });
  return readJSONResponse<T>(response, path);
}

async function readJSONResponse<T>(response: Response, path: string): Promise<T> {
  if (response.status === 204) {
    if (!response.ok) throw new APIError("API request failed.", response.status);
    return undefined as T;
  }
  const contentType = response.headers.get("content-type") || "";
  if (!contentType.includes("application/json")) {
    if (canUseMockFallback(path)) return mockGet(path) as T;
    throw new APIError("API response was not JSON.", response.status, "non_json_response", contentType);
  }
  let data;
  try {
    data = await response.json();
  } catch {
    throw new APIError("API response JSON could not be parsed.", response.status, "invalid_json_response", contentType);
  }
  if (!response.ok) {
    throw new APIError(data?.code || "API request failed.", response.status, data?.code, contentType, data?.detail_code);
  }
  if (data?.csrf_token) setCSRFToken(data.csrf_token);
  return data as T;
}

function forceMock() {
  return process.env.NEXT_PUBLIC_AUTOSTREAM_DEMO === "true";
}

function canUseMockFallback(path: string) {
  if (process.env.NEXT_PUBLIC_AUTOSTREAM_DEMO === "false") return false;
  if (typeof window === "undefined") return false;
  if (String(path || "").split("?")[0] === "/auth/me") return false;
  const devPorts = new Set(["3000", "3001", "3002", "5173"]);
  return devPorts.has(window.location.port) && mockPathExists(path);
}

